4.question:
What is the output of the following 'C' program ?
(Assuming little - endian representation of multi-byte data in which Least Significant Byte (LSB) is stored at the lowest memory address.)
#include <stdio.h>
#include <stdlib.h>
/* Assume short int occupies two bytes of storage */
int main ( )
{
    union saving
    {
        short int one;
        char two[2];
    };
    union saving m;
    m.two [0] = 5;
    m.two [1] = 2;
    printf('%%d, %d, %d\n", m.two [0], m.two [1], m.one);
}/* end of main */

5.question:
Given below are three implementations of the swap( ) function in C++ :
(a)
void swap (int a, int b)
{
int temp;
temp = a;
a = b;
b = temp;
}
int main( )
{
int p = 0, q = 1;
swap (p, q);
}
(b)
void swap (int &a, int &b)
{
int temp;
temp = a;
a = b;
b = temp;
}
int main( )
{
int p = 0, q = 1;
swap (p, q);
}
(c)
void swap (int *a, int *b)
{
int *temp;
temp = a;
a = b;
b = temp;
}
int main( )
{
int p = 0, q = 1;
swap (&p, &q);
}
Which of these would actually swap the contents of the two integer variables p and q ?
